import type { IKeyValueStore } from "../store/KeyValueStore.ts";
import type { IDeviceKeys } from "../@types/crypto.ts";
import { logger } from "../logger.ts";

export type VerificationStatus = "unverified" | "verifying" | "verified" | "blocked";

export interface DeviceInfo {
    deviceId: string;
    userId: string;
    keys: IDeviceKeys;
    displayName?: string;
    lastSeenIp?: string;
    lastSeenTs?: number;
    trustLevel: "unverified" | "verified" | "blocked";
}

export interface VerificationRequest {
    requestId: string;
    deviceId: string;
    userId: string;
    status: VerificationStatus;
    timestamp: number;
    methods: string[];
}

export interface DeviceVerificationOptions {
    autoVerifyTrusted?: boolean;
    verificationTimeout?: number;
}

export class DeviceVerification {
    private devices: Map<string, DeviceInfo> = new Map();
    private verificationRequests: Map<string, VerificationRequest> = new Map();
    private autoVerifyTrusted: boolean;
    private verificationTimeout: number;

    public constructor(
        private store: IKeyValueStore,
        options: DeviceVerificationOptions = {},
    ) {
        this.autoVerifyTrusted = options.autoVerifyTrusted ?? false;
        this.verificationTimeout = options.verificationTimeout ?? 300000;

        this.loadDevices();
    }

    public async getDevice(userId: string, deviceId: string): Promise<DeviceInfo | null> {
        const key = this.getDeviceKey(userId, deviceId);
        return this.devices.get(key) ?? null;
    }

    public async getDevices(userId: string): Promise<DeviceInfo[]> {
        const userDevices: DeviceInfo[] = [];

        for (const [key, device] of this.devices.entries()) {
            if (key.startsWith(`${userId}:`)) {
                userDevices.push(device);
            }
        }

        return userDevices;
    }

    public async verifyDevice(userId: string, deviceId: string): Promise<void> {
        const device = await this.getDevice(userId, deviceId);

        if (!device) {
            throw new Error(`Device not found: ${deviceId}`);
        }

        device.trustLevel = "verified";
        this.devices.set(this.getDeviceKey(userId, deviceId), device);
        await this.saveDevice(device);

        logger.info(`Device verified: ${userId}:${deviceId}`);
    }

    public async blockDevice(userId: string, deviceId: string): Promise<void> {
        const device = await this.getDevice(userId, deviceId);

        if (!device) {
            throw new Error(`Device not found: ${deviceId}`);
        }

        device.trustLevel = "blocked";
        this.devices.set(this.getDeviceKey(userId, deviceId), device);
        await this.saveDevice(device);

        logger.info(`Device blocked: ${userId}:${deviceId}`);
    }

    public async unverifyDevice(userId: string, deviceId: string): Promise<void> {
        const device = await this.getDevice(userId, deviceId);

        if (!device) {
            throw new Error(`Device not found: ${deviceId}`);
        }

        device.trustLevel = "unverified";
        this.devices.set(this.getDeviceKey(userId, deviceId), device);
        await this.saveDevice(device);

        logger.info(`Device unverified: ${userId}:${deviceId}`);
    }

    public async startVerification(userId: string, deviceId: string, methods: string[]): Promise<string> {
        const requestId = this.generateRequestId();

        const request: VerificationRequest = {
            requestId,
            deviceId,
            userId,
            status: "verifying",
            timestamp: Date.now(),
            methods,
        };

        this.verificationRequests.set(requestId, request);
        await this.saveVerificationRequest(request);

        logger.info(`Verification started: ${requestId} for ${userId}:${deviceId}`);

        return requestId;
    }

    public async confirmVerification(requestId: string, verified: boolean): Promise<void> {
        const request = this.verificationRequests.get(requestId);

        if (!request) {
            throw new Error(`Verification request not found: ${requestId}`);
        }

        if (verified) {
            await this.verifyDevice(request.userId, request.deviceId);
        } else {
            await this.unverifyDevice(request.userId, request.deviceId);
        }

        request.status = verified ? "verified" : "unverified";
        this.verificationRequests.set(requestId, request);
        await this.saveVerificationRequest(request);

        logger.info(`Verification confirmed: ${requestId} - ${verified ? "verified" : "unverified"}`);
    }

    public async cancelVerification(requestId: string): Promise<void> {
        const request = this.verificationRequests.get(requestId);

        if (!request) {
            throw new Error(`Verification request not found: ${requestId}`);
        }

        request.status = "unverified";
        this.verificationRequests.set(requestId, request);
        await this.saveVerificationRequest(request);

        logger.info(`Verification cancelled: ${requestId}`);
    }

    public getVerificationRequest(requestId: string): VerificationRequest | null {
        return this.verificationRequests.get(requestId) ?? null;
    }

    public getVerificationRequests(userId?: string): VerificationRequest[] {
        let requests = Array.from(this.verificationRequests.values());

        if (userId) {
            requests = requests.filter((r) => r.userId === userId);
        }

        return requests.sort((a, b) => b.timestamp - a.timestamp);
    }

    public async updateDeviceKeys(userId: string, deviceId: string, keys: IDeviceKeys): Promise<void> {
        const key = this.getDeviceKey(userId, deviceId);
        let device = this.devices.get(key);

        if (!device) {
            device = {
                deviceId,
                userId,
                keys,
                trustLevel: "unverified",
            };
        } else {
            device.keys = keys;
        }

        this.devices.set(key, device);
        await this.saveDevice(device);

        if (this.autoVerifyTrusted) {
            await this.autoVerifyDevice(device);
        }
    }

    public async deleteDevice(userId: string, deviceId: string): Promise<void> {
        const key = this.getDeviceKey(userId, deviceId);
        this.devices.delete(key);
        await this.store.deleteItem(`device_${key}`);

        logger.info(`Device deleted: ${userId}:${deviceId}`);
    }

    public async cleanupExpiredRequests(): Promise<number> {
        const now = Date.now();
        const expiredRequests: string[] = [];

        for (const [requestId, request] of this.verificationRequests.entries()) {
            if (now - request.timestamp > this.verificationTimeout) {
                expiredRequests.push(requestId);
            }
        }

        for (const requestId of expiredRequests) {
            await this.cancelVerification(requestId);
            this.verificationRequests.delete(requestId);
            await this.store.deleteItem(`verification_request_${requestId}`);
        }

        if (expiredRequests.length > 0) {
            logger.info(`Cleaned up ${expiredRequests.length} expired verification requests`);
        }

        return expiredRequests.length;
    }

    public getDeviceCount(userId?: string): number {
        if (userId) {
            let count = 0;
            for (const key of this.devices.keys()) {
                if (key.startsWith(`${userId}:`)) {
                    count++;
                }
            }
            return count;
        }
        return this.devices.size;
    }

    public getVerifiedDeviceCount(userId?: string): number {
        let count = 0;

        for (const device of this.devices.values()) {
            if (device.trustLevel === "verified") {
                if (!userId || device.userId === userId) {
                    count++;
                }
            }
        }

        return count;
    }

    private async autoVerifyDevice(device: DeviceInfo): Promise<void> {
        if (device.trustLevel !== "unverified") {
            return;
        }

        const isTrusted = this.isDeviceTrusted(device);

        if (isTrusted) {
            await this.verifyDevice(device.userId, device.deviceId);
        }
    }

    private isDeviceTrusted(device: DeviceInfo): boolean {
        return device.keys.algorithms.includes("m.olm.v1.curve25519-aes-sha2");
    }

    private getDeviceKey(userId: string, deviceId: string): string {
        return `${userId}:${deviceId}`;
    }

    private generateRequestId(): string {
        return `verify_${Date.now()}_${Math.random().toString(36).substring(2)}`;
    }

    private async saveDevice(device: DeviceInfo): Promise<void> {
        const key = this.getDeviceKey(device.userId, device.deviceId);
        await this.store.setItem(`device_${key}`, device);
    }

    private async saveVerificationRequest(request: VerificationRequest): Promise<void> {
        await this.store.setItem(`verification_request_${request.requestId}`, request);
    }

    private async loadDevices(): Promise<void> {
        try {
            const keys = await this.listStoredDeviceKeys();

            for (const key of keys) {
                const device = await this.store.getItem<DeviceInfo>(`device_${key}`);
                if (device) {
                    this.devices.set(key, device);
                }
            }

            logger.info(`Loaded ${this.devices.size} devices`);
        } catch (error) {
            logger.warn("Failed to load devices:", error);
        }
    }

    private async listStoredDeviceKeys(): Promise<string[]> {
        const keys: string[] = [];

        try {
            const storedKeys = await this.store.getItem<string[]>("device_keys_list");
            if (storedKeys) {
                return storedKeys;
            }
        } catch {}

        return keys;
    }
}
